# Import Django URL tools
from django.urls import path, include

# Import Django REST Framework router
from rest_framework.routers import DefaultRouter

# Import ViewSets from viewsets.py
from .viewsets import DogViewSet, BreedViewSet


# The router automatically creates REST API URLs.
router = DefaultRouter()

# Register the Dog ViewSet
router.register(
    r'dogs',
    DogViewSet,
    basename='dog'
)

# Register the Breed ViewSet
router.register(
    r'breeds',
    BreedViewSet,
    basename='breed'
)


# Include all URLs generated by the router.
urlpatterns = [
    path('', include(router.urls)),
]